@layer hj.components {
  /* Customise: --hj-text-color (overrides tone) */
  .hj-text {
    --_r: var(--hj-type-body);
    --_t: var(--hj-tracking-body);
    margin: 0;
    font: var(--_r);
    letter-spacing: var(--_t);
    color: var(--hj-text-color, inherit);
  }
  .hj-text[data-variant='hero'] {
    --_r: var(--hj-type-hero);
    --_t: var(--hj-tracking-hero);
    font-variant-numeric: tabular-nums;
  }
  .hj-text[data-variant='display'] {
    --_r: var(--hj-type-display);
    --_t: var(--hj-tracking-display);
  }
  .hj-text[data-variant='title'] {
    --_r: var(--hj-type-title);
    --_t: var(--hj-tracking-title);
  }
  .hj-text[data-variant='heading'] {
    --_r: var(--hj-type-heading);
    --_t: var(--hj-tracking-heading);
  }
  .hj-text[data-variant='subheading'] {
    --_r: var(--hj-type-subheading);
    --_t: var(--hj-tracking-subheading);
  }
  .hj-text[data-variant='sub'] {
    --_r: var(--hj-type-sub);
    --_t: var(--hj-tracking-sub);
  }
  .hj-text[data-variant='label'] {
    --_r: var(--hj-type-label);
    --_t: var(--hj-tracking-label);
  }
  .hj-text[data-variant='eyebrow'] {
    --_r: var(--hj-type-eyebrow);
    --_t: var(--hj-tracking-eyebrow);
    text-transform: uppercase;
  }
  .hj-text[data-variant='mono'] {
    --_r: var(--hj-type-mono);
    --_t: var(--hj-tracking-mono);
    font-variant-numeric: tabular-nums;
  }

  .hj-text[data-tone='fg'] {
    color: var(--hj-text-color, var(--hj-fg));
  }
  .hj-text[data-tone='dim'] {
    color: var(--hj-text-color, var(--hj-fg-dim));
  }
  .hj-text[data-tone='mute'] {
    color: var(--hj-text-color, var(--hj-fg-mute));
  }
  .hj-text[data-tone='accent'] {
    color: var(--hj-text-color, var(--hj-accent-text));
  }
  .hj-text[data-tone='danger'] {
    color: var(--hj-text-color, var(--hj-danger-text));
  }
  .hj-text[data-tone='success'] {
    color: var(--hj-text-color, var(--hj-success-text));
  }

  .hj-text[data-truncate] {
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

/** hanji's type roles. `hero` is one number per screen; `mono` is for timecodes and values. */
export type TextVariant =
  | 'hero'
  | 'display'
  | 'title'
  | 'heading'
  | 'subheading'
  | 'body'
  | 'sub'
  | 'label'
  | 'eyebrow'
  | 'mono';

/** Props hanji adds to a plain element. */
export interface TextOwnProps {
  /** The type role. Sets size, weight, line height and tracking from the tokens. */
  variant?: TextVariant;
  /** Ink. Omit to inherit the surrounding colour. Muted ink is for plain surfaces only. */
  tone?: 'fg' | 'dim' | 'mute' | 'accent' | 'danger' | 'success';
  /** Clip to one line with an ellipsis. */
  truncate?: boolean;
  /** Replace the element (e.g. `<h1 />` for a page title) or compose with your own component. */
  render?: useRender.RenderProp;
}

export interface TextProps extends TextOwnProps, Omit<React.ComponentProps<'p'>, 'className'> {
  className?: string;
}

/** Default element per role. Headings are a guess — pass `render` to fit the page's outline. */
const TAGS: Readonly<Record<TextVariant, keyof React.JSX.IntrinsicElements>> = {
  hero: 'p',
  display: 'h1',
  title: 'h2',
  heading: 'h3',
  subheading: 'h4',
  body: 'p',
  sub: 'p',
  label: 'span',
  eyebrow: 'span',
  mono: 'span',
};

/**
 * Text in one of hanji's nine roles (plus `hero`). Character comes from how the sans is set —
 * weight and tight tracking at the top, plain at reading size — and numbers are always tabular.
 *
 * @example
 * <Text variant="eyebrow" tone="mute">Now playing</Text>
 * <Text variant="title" render={<h1 />}>Recently played</Text>
 */
export function Text(props: TextProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    variant = 'body',
    tone,
    truncate = false,
    render,
    className,
    ...rest
  } = withDefaults(config, 'Text', props);
  return useRender({
    render,
    defaultTagName: TAGS[variant],
    props: {
      ...rest,
      'data-variant': variant,
      'data-tone': tone,
      'data-truncate': flag(truncate),
      className: cls(config, 'Text', 'hj-text', className) as string | undefined,
    },
  });
}
